/* Shared data is generated by scripts/build-directory.py. No remote API or tracking. */
(() => {
  'use strict';
  const rows = window.AI_RESOURCES;
  const labels = {llm:'LLM APIs',local:'Local tools',models:'Open models',coding:'Coding assistants',image:'Image & video',hosting:'Hosting',rag:'Embeddings & RAG',audio:'Speech & audio',agents:'Agents & workflows'};
  const $ = id => document.getElementById(id);
  const controls = ['search','category','kind','card','reviewed','favorites'];
  let saved = new Set();
  try { const stored = JSON.parse(localStorage.getItem('ai-bible-saved') || '[]'); if (Array.isArray(stored)) saved = new Set(stored.filter(x => typeof x === 'string')); } catch (_) { /* Storage can be disabled. */ }
  Object.entries(labels).forEach(([value, name]) => { const option = document.createElement('option'); option.value = value; option.textContent = name; $('category').append(option); });
  const params = new URLSearchParams(location.search);
  controls.forEach(id => { const el = $(id); if (!params.has(id)) return; if (el.type === 'checkbox') el.checked = params.get(id) === '1'; else el.value = params.get(id); });
  function node(tag, cls, text) { const el = document.createElement(tag); if (cls) el.className = cls; if (text) el.textContent = text; return el; }
  function link(text, url, cls) { const el = node('a', cls, text); el.href = url; return el; }
  function syncURL() {
    const next = new URLSearchParams();
    controls.forEach(id => { const el = $(id); if (el.type === 'checkbox') { if (id === 'reviewed' || el.checked) next.set(id, el.checked ? '1' : '0'); } else if (el.value) next.set(id, el.value); });
    history.replaceState(null, '', location.pathname + (next.size ? '?' + next.toString() : '') + location.hash);
  }
  function render() {
    const query = $('search').value.trim().toLowerCase();
    const words = query.split(/\s+/).filter(Boolean);
    const found = rows.filter(r => {
      const text = [r.name,r.summary,r.limits,r.category,labels[r.category],...r.tags].join(' ').toLowerCase();
      return words.every(w => text.includes(w)) && (!$('category').value || r.category === $('category').value) && (!$('kind').value || r.kind === $('kind').value) && (!$('card').value || r.card === $('card').value) && (!$('reviewed').checked || r.verification === 'docs-reviewed') && (!$('favorites').checked || saved.has(r.id));
    });
    $('count').textContent = `${found.length} of ${rows.length} resources · ${rows.filter(r => r.verification === 'docs-reviewed').length} docs reviewed`;
    $('results').replaceChildren();
    if (!found.length) $('results').append(node('p','empty','No matches. Try fewer filters or turn off “Docs reviewed only” to see entries awaiting review.'));
    found.forEach(r => {
      const card = node('article','card');
      card.append(node('div','badge',`${labels[r.category]} / ${r.kind}`));
      const title = node('h2'); title.append(link(r.name,r.url)); card.append(title,node('p','',r.summary),node('p','limits',`${r.limits} Card: ${r.card}.`));
      const foot = node('div','cardfoot');
      foot.append(link(r.reviewed ? `Official source · ${r.reviewed}` : 'Needs review · source', r.source,'source'));
      const save = node('button','save',saved.has(r.id) ? '★ Saved' : '☆ Save'); save.type='button'; save.setAttribute('aria-label',`Save ${r.name}`); save.setAttribute('aria-pressed',String(saved.has(r.id)));
      save.addEventListener('click',() => { saved.has(r.id) ? saved.delete(r.id) : saved.add(r.id); try { localStorage.setItem('ai-bible-saved',JSON.stringify([...saved])); } catch (_) { $('message').textContent='Browser storage is unavailable. Favorites will last for this session only.'; } render(); });
      foot.append(save); card.append(foot); $('results').append(card);
    });
  }
  controls.forEach(id => $(id).addEventListener(id === 'search' ? 'input' : 'change',() => { syncURL(); render(); }));
  $('reset').addEventListener('click',() => { controls.forEach(id => { const el=$(id); if (el.type === 'checkbox') el.checked = id === 'reviewed'; else el.value=''; }); syncURL(); render(); });
  $('share').addEventListener('click',async () => { syncURL(); try { await navigator.clipboard.writeText(location.href); $('message').textContent='Filtered link copied. Favorites are stored on your device and are not included in the link.'; } catch (_) { $('message').textContent='Copy this filtered link from the address bar: ' + location.href; } });
  render();
})();
